/**
 * A task: one piece of work Sinatra does, from any source.
 */
export type Task = {
    /**
     * The task's id. Use it as `taskId` in the task endpoints.
     */
    id: string;
    /**
     * Where the task is in its life, such as `pending`, `implementing`, `replied`, `pr_open` or `completed`. New statuses can appear, so don't treat the list as closed. See [Raw statuses](https://docs.sinatra.dev/docs/getting-started/how-it-works#raw-statuses) for each one.
     */
    status: string;
    /**
     * Where the task started: `api` for the CLI, MCP, this API or the dashboard, `linear` or `github_issue` for an issue, `slack` or `telegram` for a chat. Other sources can appear, so treat an unknown value as a task started elsewhere.
     */
    source: string;
    /**
     * The task's title: its issue's title, or a chat task's name. `null` for a task whose issue has no title, or a chat task not yet named.
     */
    title: string | null;
    /**
     * `owner/name` of the task's repository. `null` until a repository is chosen.
     */
    repo: string | null;
    /**
     * The task's pull request. `null` until one opens.
     */
    pullRequest: PullRequest | null;
    /**
     * `true` while the task's agent waits because the workspace is already running as many agents at a time as its plan allows. The dashboard shows this as Waiting.
     */
    queued: boolean;
    /**
     * When the task was created.
     */
    createdAt: string;
    /**
     * When the task last did something. `null` if it hasn't yet.
     */
    lastActivityAt: string | null;
    /**
     * The task's page in the Sinatra dashboard, where anyone in the workspace can follow it. On a task started from the CLI, MCP, API or dashboard they can reply there too.
     */
    url: string | null;
};

